-- ✅ Check of TASK ⭐ 7 – generated by the teacher's build script, do not edit.
-- It compares a summary (md5) of your model countries_with_many_signups with the expected one: PASS = your rows are right.
-- FAIL: the rows differ – compare rows_found with rows_expected and re-read the task.
-- ERROR: usually a column is missing or named differently – the columns must be: country, signups.
with summary as (
    select count(*) as n, md5(coalesce(string_agg(concat_ws('|', country, signups), E'\n' order by concat_ws('|', country, signups) collate "C"), '')) as h from {{ ref('countries_with_many_signups') }}
)
select n as rows_found, 2 as rows_expected
from summary
where h <> 'd8c3092578220a6857c1dcc6834835b2'
